from solution import change_base
import pytest
from hypothesis import given, strategies as st


def _reference(x: int, base: int) -> str:
    if x == 0:
        return "0"
    digits = []
    v = x
    while v > 0:
        digits.append(str(v % base))
        v //= base
    return "".join(reversed(digits))


def test_examples_given_in_spec():
    assert change_base(8, 3) == '22'
    assert change_base(8, 2) == '1000'
    assert change_base(7, 2) == '111'


def test_zero_converts_to_zero_string():
    for base in range(2, 10):
        assert change_base(0, base) == "0"


def test_result_is_nonempty_digit_string():
    @given(
        x=st.integers(min_value=0, max_value=10_000),
        base=st.integers(min_value=2, max_value=9),
    )
    def inner(x, base):
        s = change_base(x, base)
        assert isinstance(s, str)
        assert len(s) >= 1
        assert all(c in "0123456789" for c in s)

    inner()


@given(
    x=st.integers(min_value=0, max_value=50_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_round_trip_via_int_interpretation(x, base):
    s = change_base(x, base)
    assert int(s, base) == x


@given(
    x=st.integers(min_value=0, max_value=50_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_equivalence_to_reference_model(x, base):
    assert change_base(x, base) == _reference(x, base)


@given(
    x=st.integers(min_value=0, max_value=50_000),
    base=st.integers(min_value=2, max_value=9),
)
def test_digits_less_than_base_and_no_leading_zeros(x, base):
    s = change_base(x, base)
    assert all(int(c) < base for c in s)
    if x == 0:
        assert s == "0"
    else:
        assert s[0] != "0"


@given(base=st.integers(min_value=2, max_value=9))
def test_single_digit_when_x_less_than_base(base):
    @given(x=st.integers(min_value=0, max_value=8))
    def inner(x):
        if x < base:
            assert change_base(x, base) == str(x)

    inner()


def test_powers_of_base_are_one_followed_by_zeros():
    for base in range(2, 10):
        for k in range(0, 6):
            assert change_base(base**k, base) == "1" + "0" * k


def test_base_minus_one_and_base_boundaries():
    for base in range(2, 10):
        assert change_base(base - 1, base) == str(base - 1)
        assert change_base(base, base) == "10"
        assert change_base(base + 1, base) == "11"
        assert change_base(1, base) == "1"
